package canteen;
import javax.swing.*;import java.awt.*;import java.sql.*;
public class SettingsFrame extends JFrame {
 private final String user,role;private JTextField gst;private JLabel status;
 public SettingsFrame(String user,String role){this.user=user;this.role=role;if(!AuditLog.isAdmin(role)){AuditLog.requireAdmin(null,role);dispose();return;}AppStyle.setWindowIcon(this);setTitle("PIET | Settings & Profile");setSize(660,500);setLocationRelativeTo(null);JPanel p=AppStyle.page("Settings & my profile");JPanel form=AppStyle.card();JPanel fields=new JPanel(new GridLayout(0,2,12,14));fields.setOpaque(false);fields.add(new JLabel("Signed in as"));fields.add(new JLabel(user+"  •  "+role));fields.add(new JLabel("GST rate (%)"));gst=new JTextField("5.0");fields.add(gst);fields.add(new JLabel("Receipt branding"));fields.add(new JLabel("PIET Canteen (fixed)"));fields.add(new JLabel("Database connection"));status=new JLabel("Checking…");fields.add(status);form.add(fields,BorderLayout.CENTER);JPanel buttons=new JPanel(new FlowLayout(FlowLayout.RIGHT));buttons.setOpaque(false);JButton save=AppStyle.button("Save GST settings",AppStyle.BLUE),change=AppStyle.button("Change my password",AppStyle.NAVY);buttons.add(change);buttons.add(save);form.add(buttons,BorderLayout.SOUTH);p.add(form,BorderLayout.CENTER);add(p);save.addActionListener(e->save());change.addActionListener(e->changePassword());status.setText(DBConnection.isConnected()?"Connected":"Unavailable");load();}
 private void load(){try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT setting_value FROM app_settings WHERE setting_key='gst_percent'" );ResultSet r=p.executeQuery()){if(r.next())gst.setText(r.getString(1));}catch(SQLException ignored){}}
 private void save(){try{double v=Double.parseDouble(gst.getText().trim());if(v<0||v>100)throw new NumberFormatException();v=Math.round(v*100.0)/100.0;try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO app_settings(setting_key,setting_value,updated_by,updated_at) VALUES('gst_percent',?,?,CURRENT_TIMESTAMP) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by),updated_at=CURRENT_TIMESTAMP")){p.setString(1,Double.toString(v));p.setString(2,user);p.executeUpdate();}AuditLog.record(user,"GST_SETTING_CHANGED","GST rate="+v);JOptionPane.showMessageDialog(this,"GST rate saved. New bills will use this rate; existing order totals remain unchanged.");}catch(Exception e){JOptionPane.showMessageDialog(this,"Enter a GST rate from 0 to 100.\n"+e.getMessage());}}
 private void changePassword(){JPasswordField old=new JPasswordField(),a=new JPasswordField(),b=new JPasswordField();JPanel p=new JPanel(new GridLayout(0,1,5,5));p.add(new JLabel("Current password"));p.add(old);p.add(new JLabel("New password (minimum 8 characters)"));p.add(a);p.add(new JLabel("Confirm new password"));p.add(b);if(JOptionPane.showConfirmDialog(this,p,"Change password",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;char[] o=old.getPassword(),x=a.getPassword(),y=b.getPassword();if(x.length<8||!java.util.Arrays.equals(x,y)){JOptionPane.showMessageDialog(this,"New passwords must match and contain at least 8 characters.");return;}try(Connection c=DBConnection.getConnection();PreparedStatement q=c.prepareStatement("SELECT password_hash FROM users WHERE username=?")){q.setString(1,user);try(ResultSet r=q.executeQuery()){if(!r.next()||!SecurityUtil.verify(o,r.getString(1))){JOptionPane.showMessageDialog(this,"Current password is incorrect.");return;}}try(PreparedStatement u=c.prepareStatement("UPDATE users SET password_hash=?,password=NULL,must_change_password=FALSE WHERE username=?")){u.setString(1,SecurityUtil.hash(x));u.setString(2,user);u.executeUpdate();}AuditLog.record(user,"PASSWORD_CHANGED","User changed own password");JOptionPane.showMessageDialog(this,"Password changed successfully.");}catch(SQLException e){JOptionPane.showMessageDialog(this,e.getMessage());}finally{java.util.Arrays.fill(o,'\0');java.util.Arrays.fill(x,'\0');java.util.Arrays.fill(y,'\0');}}
}
